import type { FilterDataStructure, FilterForm } from 'models/Filters';

import { resetBrandHierarchyToBaseline } from './commercialResultsFilterReconciliation';

/**
 * Geographic drivers that scope every brand-hierarchy option list on
 * Commercial Results. Changing one invalidates the previous country's
 * brand/sub-brand/sku/region selection.
 */
export const COMMERCIAL_RESULTS_GEO_DRIVER_KEYS = ['zone', 'country'] as const;

export type CommercialResultsGeoDriverKey =
  (typeof COMMERCIAL_RESULTS_GEO_DRIVER_KEYS)[number];

/** True when `next` moves to a different zone/country than `prevApplied`. */
export function hasCommercialGeoChange(
  next: FilterForm | undefined,
  prevApplied: FilterForm | undefined,
): boolean {
  if (!next || !prevApplied) return false;

  return COMMERCIAL_RESULTS_GEO_DRIVER_KEYS.some(
    (key) => next[key] !== undefined && next[key] !== prevApplied[key],
  );
}

/** True when a direct patch itself changes zone/country against `prevApplied`. */
export function patchHasCommercialGeoChange(
  patch: Partial<FilterForm> | undefined,
  prevApplied: FilterForm | undefined,
): boolean {
  if (!patch || !prevApplied) return false;

  return COMMERCIAL_RESULTS_GEO_DRIVER_KEYS.some(
    (key) => key in patch && patch[key] !== prevApplied[key],
  );
}

/**
 * Only a brand inherited from the previous country is dropped: when the user
 * picks a brand in the same interaction that moves the geography (drawer flow),
 * that choice already belongs to the new country and must survive.
 */
export function shouldClearCommercialGeoDependentHierarchy(
  next: FilterForm | undefined,
  prevApplied: FilterForm | undefined,
): boolean {
  if (!hasCommercialGeoChange(next, prevApplied)) return false;

  return next?.brands === prevApplied?.brands;
}

/** Same rule for a direct patch: an explicit `brands` in the patch wins. */
export function patchShouldClearCommercialGeoDependentHierarchy(
  patch: Partial<FilterForm> | undefined,
  prevApplied: FilterForm | undefined,
): boolean {
  if (!patchHasCommercialGeoChange(patch, prevApplied)) return false;

  return !(patch && 'brands' in patch);
}

/**
 * Drops the brand hierarchy (brands/sub_brands/sku) and region back to the
 * preset baseline, since their option lists belong to the previous country.
 *
 * `region` is included because its options are keyed by country, so a stale
 * value would silently survive until the next preset round trip.
 */
export function resetCommercialGeoDependentHierarchy(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  return {
    ...resetBrandHierarchyToBaseline(dataFilters, form),
    region: dataFilters.region?.default?.value ?? 'All',
  };
}
